--   docker exec eiams-local-pg pg_dump -U postgres -d eiams --data-only --column-inserts --no-owner --no-privileges --exclude-table=audit_log_entries --exclude-table=audit_logs --exclude-table=document_lifecycle_events --exclude-table=custody_history --exclude-table=asset_movement_history --exclude-table=idempotency_records --exclude-table=pending_file_deletion --exclude-table=__EFMigrationsHistory --exclude-table=authorization_versions --exclude-table=authorization_policy_versions -f /tmp/contract-seed.sql
